draw:
var L = p.length, g = p.gravity, th0 = p.amp * Math.PI / 180;
var T0 = 2 * Math.PI * Math.sqrt(L / g);
var Tex = T0 * (1 + th0 * th0 / 16 + 11 * Math.pow(th0, 4) / 3072);
var th = th0 * Math.cos(2 * Math.PI * t / Tex);
var F = "12px ui-sans-serif, system-ui, sans-serif";

var px = W * 0.5, py = H * 0.10;
var scale = (H * 0.66) / 2.5;          // pixels per metre, longest string fits
var len = L * scale;
var bx = px + len * Math.sin(th), by = py + len * Math.cos(th);

// ceiling
ctx.fillStyle = C.faint;
ctx.fillRect(px - W * 0.3, py - 8, W * 0.6, 8);

// vertical reference
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.setLineDash([3, 5]);
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px, py + len + 24); ctx.stroke();
ctx.setLineDash([]);

// swept arc between the turning points
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.arc(px, py, len, Math.PI / 2 - th0, Math.PI / 2 + th0); ctx.stroke();

// turning point markers
ctx.fillStyle = C.faint;
ctx.beginPath(); ctx.arc(px + len * Math.sin(th0), py + len * Math.cos(th0), 4, 0, 2 * Math.PI); ctx.fill();
ctx.beginPath(); ctx.arc(px - len * Math.sin(th0), py + len * Math.cos(th0), 4, 0, 2 * Math.PI); ctx.fill();

// string and bob
ctx.strokeStyle = C.ink; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(bx, by); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(bx, by, 10, 0, 2 * Math.PI); ctx.fill();

ctx.fillStyle = C.ink; ctx.font = F;
ctx.fillText("L = " + L.toFixed(2) + " m", px + 10, py + len * 0.5);
ctx.fillText("amplitude " + p.amp.toFixed(0) + " deg", px - W * 0.28, py + 24);

// angle against time, drawn along the bottom
var gy = H * 0.90, x0 = W * 0.06, x1 = W * 0.94;
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(x0, gy); ctx.lineTo(x1, gy); ctx.stroke();
var span = 4 * Tex;                    // seconds across the plot
ctx.strokeStyle = C.accent; ctx.lineWidth = 1.5;
ctx.beginPath();
for (var i = 0; i <= 200; i++) {
  var tt = t - span * (200 - i) / 200;
  var X = x0 + (x1 - x0) * i / 200;
  var Y = gy - (H * 0.07) * Math.cos(2 * Math.PI * tt / Tex);
  i === 0 ? ctx.moveTo(X, Y) : ctx.lineTo(X, Y);
}
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("angle against time", x0, gy + 18);

out.note = "small-angle T = " + T0.toFixed(3) + " s, true T = " + Tex.toFixed(3) +
  " s, slow by " + ((Tex / T0 - 1) * 100).toFixed(2) + "%";
